    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)"
      },
      "events": {
        "put_item_in_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "return_loaded_cart": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "put_item_in_cart",
      "discharge": "return_loaded_cart"
    }
  },
  {
    "id": "no_cart_in_exit_corridor",
    "text": "Carts are forbidden in the eastern exit corridor, so shoppers must park the cart before walking to the exit door.",
    "abstraction": {
      "state_properties": {
        "exit_corridor": {
          "or": [
            "at(4,5)",
