        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "exit_corridor"
        ]
      }
    }
  },
  {
    "id": "middle_shelf_service_is_item_pickup",
    "text": "The middle-shelf service is not a generic interaction at one fixed square: it counts only as a PICKUP_ITEM from either side of the middle shelf.",
    "abstraction": {
      "state_properties": {
        "middle_shelf_access": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        }
      },
      "events": {
        "middle_shelf_pickup": {
          "pre": {
            "and": [
